      id: "NCE2-20", book: "NCE2", n: 20, title: "One Man in a Boat", titleZh: "独坐孤舟",
      audio: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE2/20OneManinaBoat.mp3", lrc: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE2/20OneManinaBoat.lrc", introLines: 1,
