      audio: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE2/21MadorNot.mp3", lrc: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE2/21MadorNot.lrc", introLines: 1,
      words: [
        { en: "aeroplane", ipa: "/ˈɛrəˌplen/", pos: "名词", zh: "飞机" },
        { en: "mad", ipa: "/mæd/", pos: "形容词", zh: "疯的" },
        { en: "determined", ipa: "/dɪˈtɝmənd/", pos: "形容词", zh: "下决心的" },
        { en: "reason", ipa: "/ˈrizən/", pos: "名词", zh: "原因" },
        { en: "sum", ipa: "/sʌm/", pos: "名词", zh: "金额" },
      ],
      text: [
        { en: "Aeroplanes are slowly driving me mad.", zh: "飞机正在逐渐把我逼疯。" },
        { en: "I live near an airport and passing planes can be heard night and day.", zh: "我住在一个机场附近，过往飞机日夜不绝于耳。" },
        { en: "The airport was built years ago, but for some reason it could not be used then.", zh: "机场是许多年前建的，但由于某种原因当时未能启用。" },
        { en: "Last year, however, it came into use.", zh: "然而去年机场开始使用了。" },
        { en: "Over a hundred people must have been driven away from their homes by the noise.", zh: "有100多人肯定是被噪音逼得已经弃家远去，" },
        { en: "I am one of the few people left.", zh: "我是少数留下来的人中的一个。" },
        { en: "Sometimes I think this house will be knocked down by a passing plane.", zh: "有时我觉得这房子就要被一架飞过的飞机撞倒。" },
        { en: "I have been offered a large sum of money to go away, but I am determined to stay here.", zh: "他们曾向我提供一大笔钱让我搬走，但我决定留在这儿。" },
        { en: "Everybody says I must be mad and they are probably right.", zh: "大家都说我肯定是疯了，也许他们说的是对的。" },
      ],
