    "NCE2-52": {
      id: "NCE2-52", book: "NCE2", n: 52, title: "A Pretty Carpet", titleZh: "漂亮的地毯",
      audio: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE2/52APrettyCarpet.mp3", lrc: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE2/52APrettyCarpet.lrc", introLines: 1,
      words: [
        { en: "actually", ipa: "/ˈækˌtʃuəli/", pos: "副词", zh: "实际上" },
        { en: "carpet", ipa: "/ˈkɑrpət/", pos: "名词", zh: "地毯" },
        { en: "gaze", ipa: "/ɡez/", pos: "动词", zh: "注视" },
        { en: "spare", ipa: "/spɛr/", pos: "形容词", zh: "空闲的" },
        { en: "temporarily", ipa: "/ˌtɛmpəˈrɛrəli/", pos: "副词", zh: "暂时地" },
        { en: "inch", ipa: "/ɪntʃ/", pos: "名词", zh: "英寸" },
        { en: "space", ipa: "/spes/", pos: "名词", zh: "空间" },
      ],
      text: [
        { en: "We have just moved into a new house and I have been working hard all morning.", zh: "我们刚刚搬进一所新房子，我辛辛苦苦地干了整整一个上午。" },
        { en: "I have been trying to get my new room in order.", zh: "我试图把我的新房间收拾整齐。" },
        { en: "This has not been easy because I own over a thousand books.", zh: "但这并不容易，因为我有1,000多本书。" },
        { en: "To make matters worse,", zh: "更糟糕的是" },
        { en: "the room is rather small,", zh: "房间还非常小，" },
        { en: "so I have temporarily put my books on the floor.", zh: "所以我暂时把书放在了地板上。" },
        { en: "At the moment, they cover every inch of floor space", zh: "这会儿，书把地板的每一点空隙都占据了，" },
        { en: "and I actually have to walk on them to get in or out of the room.", zh: "我实际上是踩着这些书进出房间的。" },
        { en: "A short while ago, my sister helped me to carry one of my old bookcases up the stairs.", zh: "几分钟前，我妹妹帮我把一个旧书橱抬上了楼。" },
        { en: "She went into my room and got a big surprise when she saw all those books on the floor.", zh: "她走进我的房间，当她看到地板上的那些书时，大吃一惊。" },
        { en: "'This is the prettiest carpet I have ever seen,' she said.", zh: "“这是我见过的最漂亮的地毯，”她说。" },
        { en: "She gazed at it for some time then added,", zh: "她盯着“地毯”看了一会儿，又说：" },
        { en: "'You don't need bookcases at all.", zh: "“你根本用不着书橱，" },
        { en: "You can sit here in your spare time and read the carpet!'", zh: "空闲时你可以坐在这儿读地毯！”" },
      ],
      expressions: [
        { en: "get sth. in order", zh: "把某物整理好", examples: ["1 I haven’t been able to get my new room in order. L43 2 Why haven’t you been able to get your new room in order?", "3 Their mom asked them to get their bedroom in order. L11 To make matters worse....", "1 she went on a diet. L51 2 he went on an excursion yesterday. L50 3 Leo went to sleep very early last night. L49 A short while ago...", "1 he smashed everything in the living room to pieces. L49 2 they heard Leo crying. L47 3 they had a picnic at the edge of a forrest. L44 help sb. to do sth.", "1 Can you help me to carry this?", "2 Would you help me to ring the bell? L51 3 They helped my family to settle down here. L38 gaze at sth.", "1 She was so cute that Leo gazed at her for a long time. L35 2 Why did you gaze at her?", "in sb’s spare time..."] },
        { en: "to make matters worse", zh: "更糟的是……", examples: [] },
        { en: "a short while ago", zh: "不久前……", examples: [] },
        { en: "help sb. to do sth", zh: "帮助某人做某事", examples: [] },
        { en: "gaze at sth", zh: "凝视某物", examples: [] },
        { en: "in sb's spare time", zh: "在某人空闲时间", examples: [] },
      ],
    },

    "NCE2-53": {
      id: "NCE2-53", book: "NCE2", n: 53, title: "Hot Snake", titleZh: "触电的蛇",
      audio: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE2/53HotSnake.mp3", lrc: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE2/53HotSnake.lrc", introLines: 1,
      words: [
        { en: "examine", ipa: "/ɪɡˈzæmɪn/", pos: "动词", zh: "检查" },
        { en: "accidentally", ipa: "/ˌæksəˈdɛntəli/", pos: "副词", zh: "意外地" },
        { en: "remains", ipa: "/rɪˈmenz/", pos: "名词", zh: "残骸" },
        { en: "wind", ipa: "/waɪnd/", pos: "动词", zh: "缠绕" },
        { en: "wire", ipa: "/ˈwaɪɚ/", pos: "名词", zh: "电线" },
        { en: "solve", ipa: "/sɑlv/", pos: "动词", zh: "解决" },
        { en: "mystery", ipa: "/ˈmɪstəri/", pos: "名词", zh: "谜" },
        { en: "snatch", ipa: "/snætʃ/", pos: "动词", zh: "抓" },
        { en: "spark", ipa: "/spɑrk/", pos: "名词", zh: "火花" },
        { en: "cause", ipa: "/kɔz/", pos: "名词", zh: "原因" },
      ],
      text: [
        { en: "At last firemen have put out a big forest fire in California.", zh: "消防队员们终于扑灭了加利福尼亚的一场森林大火。" },
        { en: "Since then, they have been trying to find out how the fire began.", zh: "从那时起，他们一直试图找出起火的原因。" },
        { en: "Forest fires are often caused by broken glass or by cigarette ends which people carelessly throw away.", zh: "森林火灾时常由破碎的玻璃或人们随手扔掉的香烟头引起。" },
        { en: "Yesterday the firemen examined the ground carefully,", zh: "昨天，消防队员仔细查看了地面，" },
        { en: "but were not able to find any broken glass.", zh: "但没有发现碎玻璃。" },
        { en: "They were also quite sure that a cigarette end did not start the fire.", zh: "他们还十分肯定火灾也不是由烟头引起的。" },
        { en: "This morning, however, a firemen accidentally discovered the cause.", zh: "然而今天上午，一个消防队员偶然发现了起火的原因。" },
        { en: "He noticed the remains of a snake which was wound round the electric wires of a 16,000-volt power line.", zh: "他发现了缠绕在16,000伏高压线上的一条死蛇。" },
        { en: "In this way, he was able to solve the mystery.", zh: "就这样，他解开了起火之谜。" },
        { en: "The explanation was simple but very unusual.", zh: "解释很简单，却异乎寻常。" },
        { en: "A bird had snatched up the snake from the ground and then dropped it on to the wires.", zh: "一只鸟把蛇从地上抓起来，然后把它扔到了电线上。" },
        { en: "The snake then wound itself round the wires.", zh: "于是蛇就缠住了几根电线。" },
        { en: "When it did so, it sent sparks down to the ground and these immediately started a fire.", zh: "当它这样做时，把火花送到了地面，这些火花立刻引起了一场大火。" },
      ],
      expressions: [
        { en: "find out", zh: "查明", examples: ["How did you find out about that?"] },
        { en: "throw away", zh: "扔掉", examples: ["I threw /θruː/ it away last night.", "Did you throw it away last night?", "when/why/who/what...."] },
        { en: "put out a fire", zh: "灭火", examples: [] },
        { en: "be caused by", zh: "由……引起", examples: [] },
        { en: "wind round", zh: "缠绕", examples: [] },
        { en: "send sparks", zh: "迸出火花", examples: [] },
      ],
    },

