    "NCE2-55": {
      id: "NCE2-55", book: "NCE2", n: 55, title: "Not a Gold Mine", titleZh: "并非金矿",
      audio: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE2/55NotaGoldMine.mp3", lrc: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE2/55NotaGoldMine.lrc", introLines: 1,
      words: [
        { en: "treasure", ipa: "/ˈtrɛʒɚ/", pos: "名词", zh: "宝藏" },
        { en: "revealer", ipa: "/rɪˈvilɚ/", pos: "名词", zh: "探测器" },
        { en: "bury", ipa: "/ˈbɛri/", pos: "动词", zh: "埋" },
        { en: "cave", ipa: "/kev/", pos: "名词", zh: "山洞" },
        { en: "seashore", ipa: "/ˈsiˌʃɔr/", pos: "名词", zh: "岸边" },
        { en: "pirate", ipa: "/ˈpaɪrət/", pos: "名词", zh: "海盗" },
        { en: "soil", ipa: "/sɔɪl/", pos: "名词", zh: "土" },
        { en: "entrance", ipa: "/ˈɛntrəns/", pos: "名词", zh: "入口" },
        { en: "thoroughly", ipa: "/ˈθəroli/", pos: "副词", zh: "彻底地" },
        { en: "trunk", ipa: "/trʌŋk/", pos: "名词", zh: "衣箱" },
        { en: "worthless", ipa: "/ˈwɝθləs/", pos: "形容词", zh: "无价值的" },
        { en: "confident", ipa: "/ˈkɑnfədənt/", pos: "形容词", zh: "自信的" },
      ],
      text: [
        { en: "Dreams of finding lost treasure almost came true recently.", zh: "最近，找到失踪宝藏的梦想差一点儿变成现实。" },
        { en: "A new machine called 'The Revealer' has been invented", zh: "一种叫“探宝器”的新机器已经发明出来，" },
        { en: "and it has been used to detect gold which has been buried in the ground.", zh: "并被人们用来探测地下埋藏的金子。" },
        { en: "The machine was used in a cave near the seashore where--it is said--pirates used to hide gold.", zh: "在靠近海边的一个据说过去海盗常在里面藏金子的岩洞里，这种机器被派上了用场。" },
        { en: "The pirates would often bury gold in the cave and then fail to collect it.", zh: "海盗们过去常把金子埋藏在那个洞里，可后来却没能取走。" },
        { en: "Armed with the new machine, a search party went into the cave hoping to find buried treasure.", zh: "一支用这种新机器装备起来的探宝队进入了这个岩洞，希望找到埋藏的金子。" },
        { en: "The leader of the party was examining the soil near the entrance to the cave when the machine showed that there was gold under the ground.", zh: "当这个队的队长正在检查洞口附近的土壤时，那台机器显示出它的下面埋有金子。" },
        { en: "Very excited, the party dug a hole two feet deep.", zh: "队员们异常激动，就地挖了一个两英尺深的坑。" },
        { en: "They finally found a small gold coin which was almost worthless.", zh: "但最后找到的是一枚几乎一钱不值的小金币。" },
        { en: "The party then searched the whole cave thoroughly but did not find anything except an empty tin trunk.", zh: "队员们接着又把整个洞彻底搜寻了一遍，但除了一只空铁皮箱外什么也没找到。" },
        { en: "In spite of this, many people are confident that 'The Revealer' may reveal something of value fairly soon.", zh: "尽管如此，很多人仍然相信“探宝器”很快就会探出值钱的东西来。" },
      ],
      expressions: [
        { en: "dreams come true", zh: "实现", examples: [] },
        { en: "be used to do sth", zh: "被用来", examples: [] },
        { en: "fairly soon", zh: "很快", examples: ["It's been a fairly interesting day so far.", "The Rock (1996) Well, it's a fairly new relationship, so we spend a lot of time together."] },
        { en: "come true", zh: "实现", examples: [] },
        { en: "be used to", zh: "被用来", examples: [] },
        { en: "fail to collect", zh: "未能收集", examples: [] },
        { en: "a search party", zh: "搜索队", examples: [] },
        { en: "in spite of", zh: "尽管", examples: [] },
        { en: "reveal something of value", zh: "揭示有价值的东西", examples: [] },
      ],
    },

