    "NCE1-77": {
      id: "NCE1-77", book: "NCE1", n: 77, title: "Terrible toothache", titleZh: "要命的牙痛",
      audio: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE1/077078TerribleToothache.mp3", lrc: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE1/077078TerribleToothache.lrc", introLines: 4,
      words: [
        { en: "appointment", ipa: "/əˈpɔɪntmənt/", pos: "名词", zh: "预约" },
        { en: "urgent", ipa: "/ˈɝdʒənt/", pos: "形容词", zh: "紧急的" },
        { en: "till", ipa: "/tɪl/", pos: "介词", zh: "直到" },
      ],
      text: [
        { en: "Good morning, Mr. Croft.", zh: "早上好，克罗夫特先生。" },
        { en: "Good morning, nurse.", zh: "早上好，护士。" },
        { en: "I want to see the dentist, please.", zh: "我想看牙医。" },
        { en: "Do you have an appointment?", zh: "您有预约吗？" },
        { en: "No, I don't.", zh: "没有，我没有预约。" },
        { en: "Is it urgent?", zh: "是急症吗？" },
        { en: "Yes, it is.", zh: "是的。" },
        { en: "It's very urgent.", zh: "很急。" },
        { en: "I feel awful.", zh: "我觉得很难受。" },
        { en: "I have a terrible toothache.", zh: "我牙疼得厉害。" },
        { en: "Can you come at 10 a.m. on Monday, April 24th?", zh: "您能在4月24日星期一上午10点来吗？" },
        { en: "I must see the dentist now, nurse.", zh: "我必须现在就看牙医，护士。" },
        { en: "The dentist is very busy at the moment.", zh: "牙医此刻很忙。" },
        { en: "Can you come at 2 p.m. ?", zh: "您能在下午2点来吗？" },
        { en: "That's very late.", zh: "那太晚了。" },
        { en: "Can the dentist see me now?", zh: "牙医能现在给我看吗？" },
        { en: "I'm afraid that he can't, Mr. Croft.", zh: "恐怕不行，克罗夫特先生。" },
        { en: "Can't you wait till this afternoon?", zh: "您不能等到今天下午吗？" },
        { en: "I can wait, but my toothache can't!", zh: "我可以等，但我的牙疼等不了！" },
      ],
      expressions: [
        { en: "have an appointment", zh: "有预约", examples: ["Do you have an appointment?"] },
        { en: "see the dentist", zh: "看牙医", examples: ["I want to see the dentist."] },
        { en: "wait till this afternoon", zh: "等到今天下午", examples: ["Wait here till I come back."] },
      ],
    },
    "NCE1-79": {
      id: "NCE1-79", book: "NCE1", n: 79, title: "Carol's shopping list", titleZh: "卡罗尔的购物单",
      audio: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE1/079080Carol'sShoppingList.mp3", lrc: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE1/079080Carol'sShoppingList.lrc", introLines: 4,
      words: [
        { en: "shopping list", ipa: "/ˈʃɑpɪŋ lɪst/", pos: "名词", zh: "购物清单" },
        { en: "vegetable", ipa: "/ˈvɛdʒtəbl/", pos: "名词", zh: "蔬菜" },
        { en: "need", ipa: "/nid/", pos: "动词", zh: "需要" },
        { en: "money", ipa: "/ˈmʌni/", pos: "名词", zh: "钱" },
        { en: "groceries", ipa: "/ˈɡrosəriz/", pos: "名词", zh: "食品杂货" },
        { en: "fruit", ipa: "/frut/", pos: "名词", zh: "水果" },
        { en: "stationery", ipa: "/ˈsteʃəˌnɛri/", pos: "名词", zh: "文具" },
        { en: "newsagent", ipa: "/ˈnjuzˌedʒənt/", pos: "名词", zh: "报刊商" },
        { en: "chemist", ipa: "/ˈkɛmɪst/", pos: "名词", zh: "药店；药剂师" },
      ],
      text: [
        { en: "What are you doing, Carol?", zh: "你在做什么，卡罗尔？" },
        { en: "I'm making a shopping list, Tom.", zh: "我在列购物清单，汤姆。" },
        { en: "What do we need?", zh: "我们需要什么？" },
        { en: "We need a lot of things this week.", zh: "这周我们需要很多东西。" },
        { en: "I must go to the grocer's.", zh: "我得去杂货店。" },
        { en: "We haven't got much tea or coffee, and we haven't got any sugar or jam.", zh: "我们的茶叶和咖啡不多了，糖和果酱也没有了。" },
        { en: "What about vegetables?", zh: "蔬菜呢？" },
        { en: "I must go to the greengroce's.", zh: "我得去蔬菜水果店。" },
        { en: "We haven't got many tomatoes, but we've got a lot of potatoes.", zh: "我们的西红柿不多了，但土豆还有很多。" },
        { en: "I must go to the butcher's, too.", zh: "我还得去肉店。" },
        { en: "We need some meat.", zh: "我们需要些肉。" },
        { en: "We haven't got any meat at all.", zh: "我们一点肉都没有了。" },
        { en: "Have we got any beer and wine?", zh: "我们有啤酒和葡萄酒吗？" },
        { en: "No, we haven't.", zh: "没有。" },
        { en: "And I'm not going to get any!", zh: "而且我不打算买！" },
        { en: "I hope that you've got some money.", zh: "我希望你有些钱。" },
        { en: "I haven't got much.", zh: "我没多少。" },
        { en: "Well, I haven't got much either!", zh: "嗯，我也没多少！" },
      ],
      expressions: [
        { en: "make a shopping list", zh: "列购物清单", examples: ["I'm making a shopping list."] },
        { en: "a lot of things", zh: "很多东西", examples: ["We need a lot of things this week."] },
        { en: "go to the grocer's", zh: "去杂货店", examples: ["I must go to the grocer's."] },
      ],
    },
